 Q=d[name+'_cap_positions'][d[name+'_aperture_vertex_ids']];poly=np.c_[400+(Q[:,0]-.009)*4000,400-(Q[:,1]-.78)*4000];maskimg=Image.new('1',(W,H));ImageDraw.Draw(maskimg).polygon([tuple(p)for p in poly],fill=1);mask=np.asarray(maskimg,bool);C=im.astype(float);blue=mask&(C[:,:,2]-C[:,:,0]>30)&(C[:,:,1]-C[:,:,0]>20);lab,n=label(blue);counts=np.bincount(lab.ravel());counts[0]=0;blue=lab==counts.argmax();yy,xx=np.nonzero(blue);points=np.c_[xx+.5,yy+.5];assert len(points)>500;hull=ConvexHull(points);hullimg=Image.new('1',(W,H));ImageDraw.Draw(hullimg).polygon([tuple(p)for p in points[hull.vertices]],fill=1);hullmask=np.asarray(hullimg,bool);white=(C[:,:,0]>90)&(abs(C[:,:,1]-C[:,:,0])<45)&(abs(C[:,:,2]-C[:,:,1])<35);edge=binary_dilation(hullmask)&~hullmask&white&mask;ey,ex=np.nonzero(edge);edgepoints=np.c_[ex+.5,ey+.5];assert len(edgepoints)>20;lo=points.min(0);hi=points.max(0);center=(lo+hi)/2;axes=(hi-lo)/2;sample=points[::max(1,len(points)//500)]
