 initial=np.r_[center,axes,0.];lower=np.r_[center-axes*.25,axes*.75,-.8];upper=np.r_[center+axes*.25,axes*1.35,.8];fit=least_squares(residual,initial,bounds=(lower,upper),loss='soft_l1',f_scale=.03,max_nfev=300);par=fit.x;gy,gx=np.meshgrid(np.arange(H)+.5,np.arange(W)+.5,indexing='ij');allr=radius(np.c_[gx.ravel(),gy.ravel()],par).reshape(H,W);lum=C@np.array([.2126,.7152,.0722]);dark=mask&(allr<.7)&(lum<45);lab,n=label(dark);counts=np.bincount(lab.ravel());counts[0]=0;pupil=binary_fill_holes(lab==counts.argmax());py,px=np.nonzero(pupil);assert len(px)>100;pp=np.c_[px+.5,py+.5];pupilcenter=pp.mean(0);cov=np.cov(pp.T);values,basis=np.linalg.eigh(cov);pupilaxes=np.sqrt(np.maximum(values,1e-6))*2;major=basis[:,-1];pupilangle=float(np.arctan2(major[1],major[0]));offset=np.linalg.norm((pupilcenter-par[:2])/par[2:4]);assert offset<.4,'Source pupil placement requires manual review';result[name]={'iris_center_pixels':par[:2].tolist(),'iris_axes_pixels':par[2:4].tolist(),'iris_rotation_radians':float(par[4]),'iris_seed_pixels':len(points),'white_boundary_samples':len(edgepoints),'boundary_radial_fit_rms':float(np.sqrt(np.mean((radius(edgepoints,par)-1)**2))),'pupil_center_pixels':pupilcenter.tolist(),'pupil_axes_pixels_minor_major':pupilaxes.tolist(),'pupil_rotation_radians_major':pupilangle,'pupil_pixels':len(pp),'pupil_center_offset_normalized':float(offset),'iris_RGB_median':np.median(C[blue],axis=0).tolist(),'iris_RGB_p20':np.quantile(C[blue],.2,axis=0).tolist(),'iris_RGB_p80':np.quantile(C[blue],.8,axis=0).tolist(),'aperture_pixels':poly.tolist()}
